        "image": "images/districts/tangail/hist-2.webp",
        "name": "Mohera Zamindar Bari",
        "nameEn": "Mohera Zamindar Bari",
        "nameBn": "মহেরা জমিদার বাড়ি",
        "category": "Greco-Roman Colonial Palace",
