        "id": 4,
        "image": "images/districts/tangail/tour-4.webp",
        "name": "Tangail Porabari Chomchom Lane",
        "nameEn": "Tangail Porabari Chomchom Lane",
        "nameBn": "পোড়াবাড়ির চমচম গলি",
        "category": "Historic Culinary Sweet Quarter",
