        "id": 5,
        "image": "images/districts/tangail/tour-5.webp",
        "name": "Karatia Zamindar Bari and Canal",
        "nameEn": "Karatia Zamindar Bari and Canal",
        "nameBn": "করটিয়া জমিদার বাড়ি ও খাল",
