        "id": 4,
        "image": "images/districts/brahmanbaria/hist-4.webp",
        "name": "Kalbhairab Temple",
        "nameEn": "Kalbhairab Temple",
        "nameBn": "কালভৈরব মন্দির",
        "category": "Monumental Hindu Shiva Shrine",
