        "id": 2,
        "image": "images/districts/coxs-bazar/hist-2.webp",
        "name": "Ramu Central Seema Bihar",
        "nameEn": "Ramu Central Seema Bihar",
        "nameBn": "রামু কেন্দ্রীয় সীমা বিহার",
