        "id": 2,
        "image": "images/districts/rajshahi/hist-2.webp",
        "name": "Varendra Research Museum",
        "nameEn": "Varendra Research Museum",
        "nameBn": "বরেন্দ্র গবেষণা জাদুঘর",
        "category": "Oldest Research & Archaeological Museum",
